-- 004_seed.sql
-- Tiny REFERENCE dataset so the API returns rows immediately after
-- `docker compose up` even before `make seed`. The bulk deterministic
-- datasets (small/medium/large) are generated by scripts/seed.py.
--
-- Seed accounts are NON-LOGIN demo rows: password_hash is a placeholder.

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('users', 'id'), GREATEST((SELECT max(id) FROM users), 1), true);

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('profiles', 'id'), GREATEST((SELECT max(id) FROM profiles), 1), true);

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('media', 'id'), GREATEST((SELECT max(id) FROM media), 1), true);

-- Posts are key-aligned-friendly in sharded mode only when inserted through
-- the application; reference rows are for the NORMALIZED first-boot DB.
ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('posts', 'id'), GREATEST((SELECT max(id) FROM posts), 1), true);

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('comments', 'id'), GREATEST((SELECT max(id) FROM comments), 1), true);

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('likes', 'id'), GREATEST((SELECT max(id) FROM likes), 1), true);

ON CONFLICT DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('notifications', 'id'), GREATEST((SELECT max(id) FROM notifications), 1), true);
